mapper.select:
SELECT a.album_no ,a.class_id ,a.content ,a.place ,a.album_date ,a.like_count FROM album a WHERE class_id = #{classId}
AND TO_NUMBER(TO_CHAR(a.album_date,'MM')) = #{month}
ORDER BY a.album_no DESC

mapper.insert:

	SELECT NVL(MAX(album_no),0) + 1
	FROM album

INSERT INTO album
		(
			album_no
			, class_id
			, content
			, place
			, album_date
			, like_count
		)
	VALUES
		(
			#{albumNo}
			, #{classId}
			, #{content}
			, #{place}
			, sysdate
			, 0
		)

mapper.update:
UPDATE album


		content = #{content},


		place = #{place}


WHERE album_no = #{albumNo}

UPDATE album 
   SET like_count = like_count + 1
 WHERE album_no = #{albumNo}

UPDATE album 
   SET like_count = like_count - 1
 WHERE album_no = #{albumNo}
